import SwiftUI

struct MovieDetailView: View {
    @State private var viewModel: MovieDetailViewModel
    var imageURLBuilder = ImageURLBuilder()

    init(movieID: Int, service: any MovieService) {
        _viewModel = State(initialValue: MovieDetailViewModel(movieID: movieID, service: service))
    }

    var body: some View {
        content
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .task { await viewModel.load() }
    }

    @ViewBuilder
    private var content: some View {
        switch viewModel.state {
        case .idle, .loading, .empty:
            ProgressView().frame(maxWidth: .infinity, maxHeight: .infinity)
        case .failed(let text):
            VStack(spacing: 12) {
                Text(text).multilineTextAlignment(.center).foregroundStyle(.secondary)
                Button("Try Again") { Task { await viewModel.load() } }
                    .buttonStyle(.borderedProminent)
            }
            .padding()
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        case .loaded(let content):
            ScrollView { details(content) }
                .navigationTitle(content.detail.title)
        }
    }

    private func details(_ content: MovieDetailContent) -> some View {
        let detail = content.detail
        return VStack(alignment: .leading, spacing: 16) {
            backdrop(detail.backdropPath)
            HStack(alignment: .top, spacing: 12) {
                image(detail.posterPath, size: .w342, width: 100, height: 150)
                VStack(alignment: .leading, spacing: 6) {
                    Text(detail.title).font(.title2.bold())
                    if let tagline = detail.tagline, !tagline.isEmpty {
                        Text(tagline).font(.subheadline.italic()).foregroundStyle(.secondary)
                    }
                    Label(detail.ratingText, systemImage: "star.fill").foregroundStyle(.orange)
                    Text([detail.year, content.runtimeText].compactMap { $0 }.joined(separator: " · "))
                        .font(.subheadline).foregroundStyle(.secondary)
                    if !content.genresText.isEmpty {
                        Text(content.genresText).font(.subheadline).foregroundStyle(.secondary)
                    }
                }
            }
            .padding(.horizontal)

            if !detail.overview.isEmpty {
                Text(detail.overview).padding(.horizontal)
            }
            if !content.directors.isEmpty {
                Text("Director: " + content.directors.map(\.name).joined(separator: ", "))
                    .font(.subheadline.weight(.semibold))
                    .padding(.horizontal)
            }
            if !content.cast.isEmpty {
                castList(content.cast)
            }
        }
        .padding(.bottom)
    }

    private func backdrop(_ path: String?) -> some View {
        image(path, size: .w780, width: nil, height: 200)
    }

    private func image(_ path: String?, size: ImageURLBuilder.Size, width: CGFloat?, height: CGFloat) -> some View {
        AsyncImage(url: imageURLBuilder.url(path: path, size: size)) { image in
            image.resizable().scaledToFill()
        } placeholder: {
            ZStack {
                Rectangle().fill(.quaternary)
                Image(systemName: "film").foregroundStyle(.secondary)
            }
        }
        .frame(width: width, height: height)
        .frame(maxWidth: width == nil ? .infinity : nil)
        .clipped()
        .accessibilityHidden(true)
    }

    private func castList(_ cast: [CastMember]) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Text("Cast").font(.headline).padding(.horizontal)
            ScrollView(.horizontal, showsIndicators: false) {
                LazyHStack(alignment: .top, spacing: 12) {
                    ForEach(cast) { member in
                        VStack(spacing: 4) {
                            image(member.profilePath, size: .w185, width: 80, height: 120)
                                .clipShape(RoundedRectangle(cornerRadius: 6))
                            Text(member.name).font(.caption.weight(.semibold)).lineLimit(2)
                            if let character = member.character, !character.isEmpty {
                                Text(character).font(.caption2).foregroundStyle(.secondary).lineLimit(2)
                            }
                        }
                        .frame(width: 80)
                        .accessibilityElement(children: .combine)
                    }
                }
                .padding(.horizontal)
            }
        }
    }
}
